// companies.js
var $ = (id) => document.getElementById(id);
var esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
var tags = ["\u5168\u90E8", "\u4E3B\u52A8\u6743\u76CA", "\u6307\u6570 / ETF", "\u56FA\u6536", "\u91CF\u5316", "\u9EC4\u91D1", "\u6D77\u5916\u6295\u8D44", "\u517B\u8001\u914D\u7F6E"];
var active = "\u5168\u90E8";
var products = {};
$("companyFilters").innerHTML = tags.map((t) => `<button type="button" data-filter="${esc(t)}" aria-pressed="${t === active}">${esc(t)}</button>`).join("");
function card(c) {
  return `<article class="company-card" id="${c.id}"><header class="company-card-head"><div class="company-kicker"><span>\u57FA\u91D1\u7BA1\u7406\u516C\u53F8</span><span>\u516C\u53F8\u753B\u50CF</span></div><h2>${c.name}</h2><p class="company-headline">${c.headline}</p><div class="company-tags">${c.tags.map((t) => `<span>${t}</span>`).join("")}</div></header><div class="company-card-body"><h3>\u6295\u8D44\u98CE\u683C \xB7 \u8D44\u6599\u5F52\u7EB3</h3><p class="company-style">${c.style}</p><h3>\u7279\u8272\u9886\u57DF\u4E0E\u4E1A\u52A1\u79EF\u7D2F</h3><div class="company-areas">${c.areas.map(([name, body]) => `<section><h4>${name}</h4><p>${body}</p></section>`).join("")}</div><details class="company-details"><summary>\u770B\u4F9D\u636E\u3001\u9009\u57FA\u8981\u70B9\u4E0E\u793A\u4F8B\u4EA7\u54C1</summary><section><span class="fact-label">\u516C\u5F00\u4E8B\u5B9E</span><p>${c.fact}</p><div class="company-sources">${c.sources.map(([title, url]) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${title}</a>`).join("")}</div></section><section><span class="fact-label interpret">\u672C\u7AD9\u89E3\u8BFB</span><p>${c.take}</p><ul>${c.checks.map((t) => `<li>${t}</li>`).join("")}</ul></section><section><h3>\u7528\u5177\u4F53\u4EA7\u54C1\u9A8C\u8BC1\u5DEE\u5F02</h3><p>\u793A\u4F8B\u5E76\u975E\u4F18\u9009\u6392\u540D\uFF0C\u70B9\u51FB\u540E\u53EF\u52A0\u5165\u540C\u677F\u5757\u5BF9\u6BD4\u3002</p><div class="company-products">${c.products.map((code) => {
    const p = products[code];
    return p ? `<a href="/compare.html?code=${code}"><span>${esc(p.name)}<small>${code} \xB7 ${esc(p.type)}</small></span><b>\u53BB\u5BF9\u6BD4</b></a>` : "";
  }).join("") || "<p>\u4EA7\u54C1\u793A\u4F8B\u5C1A\u672A\u8F7D\u5165\uFF0C\u53EF\u5148\u67E5\u770B\u516C\u53F8\u6765\u6E90\u3002</p>"}</div></section></details><footer class="company-card-footer"><span>\u8D44\u6599\u6838\u5BF9 ${reviewedAt}</span><a href="/compare.html?q=${encodeURIComponent(c.short)}">\u641C\u7D22\u65D7\u4E0B\u57FA\u91D1</a></footer></div></article>`;
}
function render() {
  const openIds = [...document.querySelectorAll(".company-details[open]")].map((d) => d.closest("article").id);
  const q = $("companyQuery").value.trim().toLowerCase();
  const rows = companies.filter((c) => (active === "\u5168\u90E8" || c.tags.includes(active)) && [c.name, c.headline, c.style, ...c.tags, ...c.areas.flat()].join(" ").toLowerCase().includes(q));
  $("companyCount").textContent = `${rows.length} / ${companies.length} \u5BB6 \xB7 \u7279\u8272\u5E03\u5C40\uFF0C\u4E0D\u4F5C\u6536\u76CA\u6392\u540D`;
  $("companyGrid").innerHTML = rows.map(card).join("") || '<div class="company-empty"><h2>\u6682\u672A\u6536\u5F55\u7B26\u5408\u6761\u4EF6\u7684\u516C\u53F8\u753B\u50CF</h2><p>\u672C\u9875\u9996\u6279\u6574\u74068\u5BB6\uFF0C\u53EF\u66F4\u6362\u5173\u952E\u8BCD\uFF0C\u6216\u6E05\u9664\u6761\u4EF6\u67E5\u770B\u5168\u90E8\u3002</p><button id="clearCompanies">\u6E05\u9664\u7B5B\u9009</button></div>';
  for (const id of openIds) {
    const details = document.getElementById(id)?.querySelector("details");
    if (details) details.open = true;
  }
  for (const b of $("companyFilters").querySelectorAll("button")) b.setAttribute("aria-pressed", String(b.dataset.filter === active));
}
function openLinkedCompany() {
  const id = location.hash.slice(1);
  if (!companies.some((c) => c.id === id)) return;
  active = "\u5168\u90E8";
  $("companyQuery").value = "";
  render();
  const card2 = document.getElementById(id);
  card2.querySelector("details").open = true;
  card2.scrollIntoView({ block: "start" });
}
$("companyQuery").addEventListener("input", render);
$("companyFilters").addEventListener("click", (e) => {
  const b = e.target.closest("[data-filter]");
  if (b) {
    active = b.dataset.filter;
    render();
  }
});
$("companyGrid").addEventListener("click", (e) => {
  if (e.target.closest("#clearCompanies")) {
    active = "\u5168\u90E8";
    $("companyQuery").value = "";
    render();
    $("companyQuery").focus();
  }
});
render();
openLinkedCompany();
window.addEventListener("hashchange", openLinkedCompany);
try {
  const response = await fetch("/company-products.json");
  if (!response.ok) throw Error();
  products = await response.json();
  render();
} catch {
  document.querySelectorAll(".company-products").forEach((el) => el.innerHTML = "<p>\u4EA7\u54C1\u793A\u4F8B\u6682\u672A\u53D6\u5F97\uFF0C\u8BF7\u901A\u8FC7\u5361\u7247\u5E95\u90E8\u641C\u7D22\u65D7\u4E0B\u57FA\u91D1\u3002</p>");
}
